function info(r){return {type:'room',code:r.code,mode:r.mode,phase:r.phase,deadline:r.deadline,now:Date.now(),map:r.map,players:[...r.members.values()].map(m=>({id:String(m.id),name:m.name,ci:m.ci,map:m.map,connected:streams.has(m.id)}))}}
