function leave(id){let r=roomFor(id);if(!r)return;r.sim?.disconnect(String(id));r.members.delete(id);if(!r.members.size){rooms.delete(r.code);return}if(r.phase==='lobby'&&r.mode==='quick')r.deadline=r.members.size>=2?Date.now()+12000:null;inform(r)}
function offers(r){if(r.mode!=='ai'&&r.members.size<2)throw Error('At least two players are needed.');r.phase='upgrade';r.deadline=Date.now()+12000;let votes=[0,0];for(let m of r.members.values())if(m.map===0||m.map===1)votes[m.map]++;r.map=votes[0]===votes[1]?randomInt(2):votes[0]>votes[1]?0:1;for(let m of r.members.values()){let pool=[0,1,2,3,4];for(let i=4;i>0;i--){let j=randomInt(i+1);[pool[i],pool[j]]=[pool[j],pool[i]]}m.offers=pool.slice(0,3);m.upgrade=null}inform(r)}
