function action(u,d){if(d.type==='leave'){leave(u.id);send(u.id,{type:'left'});return}if(d.type==='join'){if(!streams.has(u.id))throw Error('Wait for the server connection.');let ci=champion(u,d.ci);if(!['quick','private','ai','code'].includes(d.mode))throw Error('Invalid mode.');let r;if(d.mode==='code'){r=rooms.get(String(d.code||'').toUpperCase());if(!r||r.mode!=='private'||r.phase!=='lobby'||r.members.size>=6)throw Error('Room unavailable, full, or currently playing.')}else if(d.mode==='quick')r=[...rooms.values()].filter(r=>r.mode==='quick'&&r.phase==='lobby'&&r.members.size<6).sort((a,b)=>b.members.size-a.members.size)[0];if(!r&&rooms.size>=Number(process.env.MAX_ROOMS||4))throw Error('Server rooms are full. Try again shortly.');leave(u.id);if(!r){let code;do{code=Array.from({length:4},()=>String.fromCharCode(65+randomInt(26))).join('')}while(rooms.has(code));r={code,mode:d.mode,members:new Map(),phase:'lobby',deadline:null,map:0,difficulty:['easy','normal','hard'].includes(d.difficulty)?d.difficulty:'normal'};rooms.set(code,r)}r.members.set(u.id,{id:u.id,name:u.name,ci,map:d.map===-1?-1:d.map===1?1:0,offers:[],upgrade:null,lastInput:Date.now(),seq:-1});if(r.mode==='quick'&&r.members.size>=2&&!r.deadline)r.deadline=Date.now()+12000;inform(r);if(r.mode==='ai')offers(r);return}
let r=roomFor(u.id),m=r?.members.get(u.id);if(!m)throw Error('Join a room first.');if(d.type==='start'&&r.phase!=='lobby')return;if(d.type==='menu'){if(r.phase==='result'){r.phase='lobby';r.sim=null;r.result=null;r.deadline=null;inform(r)}else send(u.id,info(r));return;}if(d.type==='select'&&r.phase==='lobby'){m.ci=champion(u,d.ci);m.map=d.map===-1?-1:d.map===1?1:0;inform(r)}else if(d.type==='start'&&r.phase==='lobby')offers(r);else if(d.type==='choose'&&r.phase==='upgrade'){if(!m.offers.includes(d.upgrade))throw Error('Choose one of your three offers.');m.upgrade=d.upgrade;inform(r)}else if(d.type==='again'&&r.phase==='result'){r.phase='lobby';r.sim=null;r.result=null;r.deadline=r.mode==='quick'&&r.members.size>=2?Date.now()+12000:null;inform(r);}else if(d.type==='input'&&r.phase==='play'){if(!Number.isSafeInteger(d.seq)||d.seq<=m.seq)return;for(let k of ['mx','mz','a','pitch'])if(!Number.isFinite(d[k]))return;m.seq=d.seq;m.lastInput=Date.now();r.sim.input(String(u.id),{mx:Math.max(-1,Math.min(1,d.mx)),mz:Math.max(-1,Math.min(1,d.mz)),a:Math.atan2(Math.sin(d.a),Math.cos(d.a)),pitch:Math.max(-1.43,Math.min(1.43,d.pitch)),attack:d.attack===true,a1:d.a1===true,a2:d.a2===true,a3:d.a3===true})}}
